import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CiKk3sJz.js";const g=JSON.parse('{"title":"漫画 · 第 47 话 逻辑属性进阶：一套代码适配全球语言","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.47-logical-properties.md","filePath":"comics/css/EP.47-logical-properties.md","lastUpdated":1792579602000}'),r={name:"comics/css/EP.47-logical-properties.md"};function l(c,e,d,s,n,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-47-话-逻辑属性进阶-一套代码适配全球语言" tabindex="-1">漫画 · 第 47 话 逻辑属性进阶：一套代码适配全球语言 <a class="header-anchor" href="#漫画-·-第-47-话-逻辑属性进阶-一套代码适配全球语言" aria-label="Permalink to &quot;漫画 · 第 47 话 逻辑属性进阶：一套代码适配全球语言&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/29-logical-properties">docs/css/29-logical-properties.md</a> ｜ 原画：<a href="./EP.47-logical-properties.svg">EP.47-logical-properties.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。站点上线阿拉伯语版，<code>margin-left: 16px</code> 在 RTL 语言下变成了右边距，边框、对齐全部错位。之前国际化都是写两套 CSS，维护成本翻倍。</li><li><strong>标签君</strong>：HTML5 结构师，搬出逻辑属性——<code>inline-start/end</code>、<code>block-start/end</code>、<code>inline-size/block-size</code>，让布局自动适配书写方向，一套代码覆盖 LTR、RTL、垂直书写。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>CSS 物理属性 left/right/top/bottom 在国际化场景下寸步难行：阿拉伯语右到左、日文竖排从上到下。逻辑属性把「物理方向」替换为「书写方向」——<code>margin-inline-start</code> 在 LTR 是左间距、RTL 是右间距，<code>block-start</code> 永远是顶部。配合逻辑简写和逻辑单位，一套 CSS 覆盖全球语言。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>RTL 语言下物理属性全错：<code>margin-left</code> 在阿拉伯语下间距出现在右侧，<code>text-align: left</code> 在希伯来语下内容右对齐成左对齐。团队被迫维护两套 CSS，新增语言就得重写。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>inline-start/end</code> 随 <code>direction</code> 翻转，LTR 为 left/right，RTL 为 right/left；<code>block-start/end</code> 永远等于 top/bottom，不受方向影响；<code>inline-size/block-size</code> 替代 width/height，在 vertical-rl 下自动互换。逻辑简写 <code>margin-inline</code> 和 <code>padding-block</code> 让代码更简洁。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：RTL 自动适配（阿拉伯语/希伯来语零改动）、垂直书写（中文古籍/日文 manga）、逻辑简写（代码更简洁）、国际化项目（CSS 代码量减少 40%）。Chrome 87+ / Safari 14.1+ / Firefox 66+ 全绿。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>inline-start/end</code> 随书写方向翻转；<code>block-start/end</code> 永远等于 top/bottom。</li><li>逻辑简写 <code>margin-inline</code> / <code>padding-block</code> 代码更简洁，推荐优先使用。</li><li><code>text-align: start</code> 自动适配 LTR/RTL，比 left/right 好——别混用物理与逻辑。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：在 <code>writing-mode: vertical-rl</code> 下，<code>inline-size</code> 和 <code>block-size</code> 分别等于什么物理属性？</p><p><strong>答</strong>：<code>vertical-rl</code> 时，内联轴是垂直方向，块轴是水平方向。因此 <code>inline-size</code> = height，<code>block-size</code> = width。逻辑属性自动完成映射，无需手动计算。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>RTL 自动适配 + 垂直书写 + 逻辑简写 + 物理 vs 逻辑对比：<a href="./../../examples/css/29-logical-properties/index-01-logical-properties.html">examples/css/29-logical-properties/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 48 话《File System Access API》——网页编辑器保存就是下载副本？打开文件选择器、保存到本地、读取目录树，浏览器原生支持直接读写本地文件系统。</p>',22)])])}const m=a(r,[["render",l]]);export{g as __pageData,m as default};
